// Build reverse map: presetName -> short code (sub-01..sub-75, se-01..se-31, etc.)
const REELS_PRESET_NAME_TO_ID = {};
for (const [code, presetName] of Object.entries(REELS_PRESET_ID_MAP)) {
    if (!REELS_PRESET_NAME_TO_ID[presetName] || /^sub-\d+$/i.test(code)) {
        REELS_PRESET_NAME_TO_ID[presetName] = code;
    }
}
function getSubtitlePresetCode(presetName) {
    if (!presetName) return '';
    return REELS_PRESET_NAME_TO_ID[String(presetName).trim()] || '';
}
function formatSubtitlePresetDisplayName(presetName) {
    const raw = String(presetName || '').trim();
    if (!raw) return '';
    const code = getSubtitlePresetCode(raw);
    if (!code || raw.startsWith(`[${code}]`)) return raw;
    return `[${code}] ${raw}`;
}

